code.solution:
def run(kind):
    log = []

    def f():
        try:
            log.append("try")
            if kind == "raise":
                raise ValueError("bad")
            if kind == "return":
                return "from try"
        except ValueError:
            log.append("except")
            return "from except"
        else:
            log.append("else")
            return "from else"
        finally:
            log.append("finally")

    return f(), log


def swallow():
    try:
        raise RuntimeError("boom")
    finally:
        return "finally wins"   # discards the in-flight RuntimeError

code.test:
assert run("ok") == ("from else", ["try", "else", "finally"])
assert run("raise") == ("from except", ["try", "except", "finally"])
assert run("return") == ("from try", ["try", "finally"])   # else is skipped when try returns
assert swallow() == "finally wins"

# an exception raised in else is NOT handled by the same try's except clauses
def else_raises():
    try:
        pass
    except ValueError:
        return "handled"
    else:
        raise ValueError("from else")

try:
    else_raises()
    raise AssertionError("should have raised")
except ValueError as e:
    assert str(e) == "from else"

answer:
Design: define one base class, class ConfigError(Exception), and derive specific errors from it (for example ConfigValueError, plus one for file problems). Callers can catch the base to handle everything from the library, or a subclass for specific handling. Derive from Exception, not BaseException, so ordinary except Exception handlers work. Do not make subclasses of ValueError and friends unless callers really benefit from catching them as such; a multiple-inheritance mix (class ConfigValueError(ConfigError, ValueError)) is possible when you need both. Keep the number of types small: add one only if a caller would handle it differently. Document them as part of the public API, and put useful context in the message (the offending value, the key).

Chaining: raise NewError(...) from exc sets __cause__ to exc and marks it explicit; the traceback shows 'The above exception was the direct cause of the following exception'. If you raise a new exception inside an except block without from, Python still records the active exception in __context__ automatically, and the traceback says 'During handling of the above exception, another exception occurred'. That wording tells readers it may be an accident or a bug in the handler. raise ... from None sets __cause__ to None and sets __suppress_context__, which hides the context from the printed traceback (the __context__ attribute is still set). Use it sparingly, when the original is an irrelevant implementation detail, such as an internal KeyError you translated into a clean public error. Default to from exc so debugging information is not thrown away.

```python
class ConfigError(Exception):
    """Base class: callers can catch this to handle any error from the library."""


class ConfigValueError(ConfigError):
    pass


def parse_port(text):
    try:
        value = int(text)
    except ValueError as exc:
        raise ConfigValueError(f"port must be an integer, got {text!r}") from exc
    if not 0 < value < 65536:
        raise ConfigValueError(f"port out of range: {value}")
    return value


def implicit_chain():
    try:
        int("x")
    except ValueError:
        raise ConfigValueError("raised without 'from'")


def suppressed_chain():
    try:
        int("x")
    except ValueError:
        raise ConfigValueError("raised 'from None'") from None
```

Avoid swallowing tracebacks: don't catch Exception just to raise a new one without chaining, and don't log-and-return None. The test checks the base-class catch, __cause__, __context__ and __suppress_context__ in all three raising styles.

code.solution:
class ConfigError(Exception):
    """Base class: callers can catch this to handle any error from the library."""


class ConfigValueError(ConfigError):
    pass


def parse_port(text):
    try:
        value = int(text)
    except ValueError as exc:
        raise ConfigValueError(f"port must be an integer, got {text!r}") from exc
    if not 0 < value < 65536:
        raise ConfigValueError(f"port out of range: {value}")
    return value


def implicit_chain():
    try:
        int("x")
    except ValueError:
        raise ConfigValueError("raised without 'from'")


def suppressed_chain():
    try:
        int("x")
    except ValueError:
        raise ConfigValueError("raised 'from None'") from None

code.test:
assert parse_port("8080") == 8080

try:
    parse_port("abc")
except ConfigError as e:                       # caught via the base class
    assert isinstance(e, ConfigValueError)
    assert isinstance(e.__cause__, ValueError)  # explicit: raise ... from exc
    assert e.__suppress_context__ is True

try:
    implicit_chain()
except ConfigError as e:
    assert e.__cause__ is None
    assert isinstance(e.__context__, ValueError)  # implicit chaining
    assert e.__suppress_context__ is False

try:
    suppressed_chain()
except ConfigError as e:
    assert e.__cause__ is None
    assert isinstance(e.__context__, ValueError)  # still recorded...
    assert e.__suppress_context__ is True         # ...but hidden from the traceback display

try:
    parse_port("70000")
except ConfigValueError as e:
    assert e.__cause__ is None and e.__context__ is None

