def chunks(items, size):
    """Split `items` into consecutive lists of at most `size` elements."""
    if size <= 0:
        raise ValueError("size must be positive")
    return [items[i:i + size] for i in range(0, len(items), size)]

code.test:
def chunks_buggy(items, size):
    return [items[i:i + size] for i in range(0, len(items) - size, size)]

# minimal reproduction found by shrinking the input
assert chunks_buggy([1, 2, 3], 2) == [[1, 2]]           # the 3 is lost
assert chunks_buggy([1, 2, 3, 4], 2) == [[1, 2]]        # even an exact multiple loses the last chunk

# the invariant an assertion would have caught
def check(items, size):
    out = chunks(items, size)
    assert [x for c in out for x in c] == items
    assert all(0 < len(c) <= size for c in out)

for n in range(0, 12):
    for size in (1, 2, 3, 5, 20):
        check(list(range(n)), size)
assert chunks([1, 2, 3], 2) == [[1, 2], [3]]
assert chunks([], 3) == []
